1	// Isolated critic for the MELEE asset reconstruction loop.
2	//
3	// runCritique is a stateless one-shot pi-ai call: it receives the source
4	// screenshot, extracted reference, current render, extraction prompt, and
5	// asset.json, and returns a structured JSON issue list. The caller is the
6	// scoring authority — the main agent never writes prose critiques or self-
7	// scores; it executes whatever issues come back and renders again.
8	
9	import { readFileSync } from "node:fs";
10	
11	import {
12	  completeSimple,
13	  type Api,
14	  type Context,
15	  type Model,
16	} from "@mariozechner/pi-ai";
17	
18	export type IssueSeverity = "blocking" | "major" | "minor";
19	
20	export interface CritiqueIssue {
21	  id: string;
22	  region: string;
23	  severity: IssueSeverity;
24	  description: string;
25	  fix_hint: string;
26	}
27	
28	export interface CritiqueResult {
29	  issues: CritiqueIssue[];
30	  verdict: string;
31	  raw: string;
32	}
33	
34	export type CritiqueOutcome =
35	  | { ok: true; result: CritiqueResult }
36	  | { ok: false; reason: "parse_failed"; rawFirst: string; rawSecond: string };
37	
38	export interface RunCritiqueInput {
39	  model: Model<Api>;
40	  auth: { apiKey?: string; headers?: Record<string, string> };
41	  sourcePngPath: string;
42	  extractedPngPath: string;
43	  renderPngPath: string;
44	  extractionPromptText: string;
45	  assetJson: string;
46	  signal?: AbortSignal;
47	}
48	
49	const CRITIC_SYSTEM_PROMPT = `<role>
50	Art-director critic. You compare a rendered HTML/CSS implementation against an
51	extracted game asset reference and report visual defects as structured JSON.
52	You have no memory of prior critiques. Every call is fresh.
53	</role>
54	
55	<inputs_you_receive>
56	1. source.png — original screenshot the asset was cut from. Ground truth for
57	   how the asset looks in situ. Use this when the extraction looks damaged,
58	   bled, or reconstructed wrong where foreground elements occluded regions.
59	2. extracted.png — isolated asset on a solid background. The primary reference
60	   the implementer is matching. Lossy: the extractor may mangle edges, drift
61	   colors slightly, or hallucinate reconstruction.
62	3. render.png — current HTML/CSS render.
63	4. extraction_prompt.txt — prompt used to generate extracted.png. Reveals
64	   whether source/extracted divergence is intentional.
65	5. asset.json — structured metadata. visual_description is authoritative for
66	   what the asset IS.
67	</inputs_you_receive>
68	
69	<category_checks>
70	Walk these first. A category defect is blocking even if pixel-level regional
71	checks pass — a technically close match to the wrong genre is still the wrong
72	asset.
73	
74	- Genre. Does the render read as the same KIND of object as the reference?
75	  MELEE assets have specific visual DNA: chunky borders, hard gradients,
76	  high-contrast fills, projected/tilted planes, glow used deliberately. A
77	  render that matches the color palette but reads as a generic modern UI
78	  panel (soft rounded corners, uniform pastel gradient, subtle drop shadow)
79	  is a blocking genre defect.
80	
81	- Slop signatures. Flag any of these as blocking:
82	  - Left-border accent stripe with soft gradient fill behind it, when the
83	    reference has nothing of the kind.
84	  - Uniform single-direction gradient standing in for a specific multi-stop
85	    gradient in the reference.
86	  - SVG paths attempting to redraw complex illustration or photographic
87	    detail from the reference when a raster region would be honest.
88	  - Corner radius applied uniformly where the reference has mixed corners
89	    (square + rounded, concave + convex).
90	  - Outer drop shadow used as a substitute for the reference's specific
91	    glow treatment.
92	
93	- Color sourcing. Sample dominant fill, border, and glow colors from the
94	  reference. If the render's values look plausible but do not match — even
95	  close — flag as color drift. Invented palettes are a blocking defect when
96	  they shift the asset's overall read, major when they only affect detail.
97	
98	- Projection. If the reference reads as a tilted or foreshortened plane, does
99	  the render match the perspective? A front-on render of a tilted reference
100	  is a blocking projection defect.
101	</category_checks>
102	
103	<regional_checks>
104	After category, walk these for every region of the asset. Compare render.png
105	against extracted.png (source.png is tiebreaker where extraction looks
106	damaged):
107	
108	- Silhouette direction per edge. For top, bottom, left, right edges: does the
109	  reference have tabs, callouts, notches, flanges, or protrusions? For each
110	  feature, state whether it extends OUTward from the panel body or cuts
111	  INward, and whether the render matches. A tab drawn inverted is a blocking
112	  silhouette defect.
113	- Corners. For each of TL, TR, BL, BR: concave (inward indent), convex
114	  (outward bump), square, or rounded? Does the render match?
115	- Dimensional drift. Reference and render should be the same size. Measure
116	  any divergence in pixels along each edge.
117	- Borders and edges. Thickness, hardness, alpha artifacting.
118	- Gradients. Direction, stops, falloff. Multi-stop gradients must be
119	  multi-stop in the render.
120	- Shadows and glows. Spread, intensity, color.
121	- Internal structure. Inner shapes, dividers, ornaments.
122	- Text. Font, weight, stroke, shadow, color, position. Text must be live
123	  text in the render, not rasterized — if it looks rasterized, flag it.
124	- Interior fill. Color, any inner gradient or texture.
125	</regional_checks>
126	
127	<non_issues>
128	Do not flag:
129	- Honest raster placeholders for sub-details the implementer could not
130	  recreate (complex illustration, character portraits, specific iconography).
131	  These will be declared in the implementation's accept notes. Judge only
132	  their color block and size, not their content.
133	- Subpixel differences in antialiasing that are invisible at native size.
134	- Font hinting differences when the correct font family is rendering.
135	- Minor wrapper-level whitespace as long as the asset bounds are correct.
136	
137	If you are unsure whether something is a real defect vs. an artifact of
138	extraction or rendering, check source.png. If the feature is present in the
139	source but not in extracted.png, the extractor is at fault and the render
140	should match source.png.
141	</non_issues>
142	
143	<severity_rules>
144	- blocking: genre defect, slop signature, silhouette-direction mismatch,
145	  wrong projection, inverted corner, missing required structural element,
146	  wrong aspect ratio, color drift that shifts the asset's overall read.
147	- major: clearly visible color drift in detail, missing visual layer (glow,
148	  inner shadow, specific border treatment), dimensional drift >4px on any
149	  edge, wrong text position, rasterized text that should be live.
150	- minor: small color drift, soft gradient falloff mismatch, subpixel edge
151	  softness, small text-shadow differences.
152	
153	If you are unsure whether something is a defect, err toward reporting it.
154	False positives are cheap; silent failures are expensive.
155	</severity_rules>
156	
157	<reply_format>
158	Return a single JSON object and nothing else — no prose before or after, no
159	markdown fences. Shape:
160	
161	{
162	  "verdict": "one sentence overall read of the match",
163	  "issues": [
164	    {
165	      "id": "I1",
166	      "region": "genre" | "slop" | "projection" | "top_edge" | "bottom_edge" | "left_edge" | "right_edge" | "top_left_corner" | "top_right_corner" | "bottom_left_corner" | "bottom_right_corner" | "tab_callout" | "interior_fill" | "border" | "glow" | "shadow" | "text" | "gradient" | "dimensional" | "color" | "other",
167	      "severity": "blocking" | "major" | "minor",
168	      "description": "what is wrong, named concretely",
169	      "fix_hint": "one-sentence suggestion; the implementer picks the actual fix"
170	    }
171	  ]
172	}
173	
174	When the render matches the reference well enough to ship, return:
175	{ "verdict": "...", "issues": [] }
176	
177	An empty issues array is the convergence signal. Use it only when you have
178	actually walked every category check AND every regional check and found no
179	defect worth reporting.
180	</reply_format>`;
181	
182	const REPLY_INSTRUCTION = `Walk every check in <what_to_check> against the three images. Return the JSON object described in <reply_format>. No prose, no markdown fences — JSON only.`;
183	
184	export async function runCritique(
185	  input: RunCritiqueInput,
186	): Promise<CritiqueOutcome> {
187	  const sourceBase64 = readFileSync(input.sourcePngPath).toString("base64");
188	  const extractedBase64 = readFileSync(input.extractedPngPath).toString(
189	    "base64",
190	  );
191	  const renderBase64 = readFileSync(input.renderPngPath).toString("base64");
192	
193	  const userText = [
194	    "Images follow in this order: source screenshot, extracted reference, current render.",
195	    "",
196	    "extraction_prompt.txt:",
197	    input.extractionPromptText.trim(),
198	    "",
199	    "asset.json:",
200	    input.assetJson.trim(),
201	    "",
202	    REPLY_INSTRUCTION,
203	  ].join("\n");
204	
205	  const context: Context = {
206	    systemPrompt: CRITIC_SYSTEM_PROMPT,
207	    messages: [
208	      {
209	        role: "user",
210	        content: [
211	          { type: "text", text: "source.png (ground truth in situ):" },
212	          { type: "image", data: sourceBase64, mimeType: "image/png" },
213	          { type: "text", text: "extracted.png (primary reference):" },
214	          { type: "image", data: extractedBase64, mimeType: "image/png" },
215	          { type: "text", text: "render.png (current implementation):" },
216	          { type: "image", data: renderBase64, mimeType: "image/png" },
217	          { type: "text", text: userText },
218	        ],
219	        timestamp: Date.now(),
220	      },
221	    ],
222	  };
223	
224	  const first = await completeSimple(input.model, context, {
225	    apiKey: input.auth.apiKey,
226	    headers: input.auth.headers,
227	    reasoning: "high",
228	    signal: input.signal,
229	  });
230	  const firstText = extractText(first.content);
231	  const firstParsed = tryParse(firstText);
232	  if (firstParsed) {
233	    return { ok: true, result: { ...firstParsed, raw: firstText } };
234	  }
235	
236	  // One retry with stricter instruction.
237	  const retryContext: Context = {
238	    systemPrompt: CRITIC_SYSTEM_PROMPT,
239	    messages: [
240	      ...context.messages,
241	      {
242	        role: "assistant",
243	        content: [{ type: "text", text: firstText }],
244	        api: first.api,
245	        provider: first.provider,
246	        model: first.model,
247	        usage: first.usage,
248	        stopReason: first.stopReason,
249	        timestamp: Date.now(),
250	      },
251	      {
252	        role: "user",
253	        content: [
254	          {
255	            type: "text",
256	            text: "Your previous reply was not valid JSON. Return the JSON object described in <reply_format> and nothing else. No prose, no markdown fences.",
257	          },
258	        ],
259	        timestamp: Date.now(),
260	      },
261	    ],
262	  };
263	
264	  const second = await completeSimple(input.model, retryContext, {
265	    apiKey: input.auth.apiKey,
266	    headers: input.auth.headers,
267	    reasoning: "high",
268	    signal: input.signal,
269	  });
270	  const secondText = extractText(second.content);
271	  const secondParsed = tryParse(secondText);
272	  if (secondParsed) {
273	    return { ok: true, result: { ...secondParsed, raw: secondText } };
274	  }
275	
276	  return {
277	    ok: false,
278	    reason: "parse_failed",
279	    rawFirst: truncate(firstText, 400),
280	    rawSecond: truncate(secondText, 400),
281	  };
282	}
283	
284	function extractText(content: Array<{ type: string; text?: string }>): string {
285	  return content
286	    .filter((c) => c.type === "text" && typeof c.text === "string")
287	    .map((c) => c.text as string)
288	    .join("\n")
289	    .trim();
290	}
291	
292	function tryParse(text: string): Omit<CritiqueResult, "raw"> | null {
293	  const stripped = stripFences(text).trim();
294	  const jsonCandidate = extractJsonObject(stripped);
295	  if (!jsonCandidate) return null;
296	  let parsed: unknown;
297	  try {
298	    parsed = JSON.parse(jsonCandidate);
299	  } catch {
300	    return null;
301	  }
302	  if (!parsed || typeof parsed !== "object") return null;
303	  const obj = parsed as Record<string, unknown>;
304	  const verdict = typeof obj.verdict === "string" ? obj.verdict : "";
305	  const rawIssues = Array.isArray(obj.issues) ? obj.issues : null;
306	  if (rawIssues === null) return null;
307	  const issues: CritiqueIssue[] = [];
308	  for (let i = 0; i < rawIssues.length; i++) {
309	    const normalized = normalizeIssue(rawIssues[i], i);
310	    if (normalized) issues.push(normalized);
311	  }
312	  return { verdict, issues };
313	}
314	
315	function normalizeIssue(raw: unknown, index: number): CritiqueIssue | null {
316	  if (!raw || typeof raw !== "object") return null;
317	  const r = raw as Record<string, unknown>;
318	  const severity = normalizeSeverity(r.severity);
319	  if (!severity) return null;
320	  return {
321	    id: typeof r.id === "string" && r.id.length > 0 ? r.id : `I${index + 1}`,
322	    region:
323	      typeof r.region === "string" && r.region.length > 0 ? r.region : "other",
324	    severity,
325	    description: typeof r.description === "string" ? r.description : "",
326	    fix_hint: typeof r.fix_hint === "string" ? r.fix_hint : "",
327	  };
328	}
329	
330	function normalizeSeverity(v: unknown): IssueSeverity | null {
331	  if (v === "blocking" || v === "major" || v === "minor") return v;
332	  return null;
333	}
334	
335	function stripFences(text: string): string {
336	  const fence = /^```(?:json)?\s*([\s\S]*?)\s*```$/m;
337	  const match = text.trim().match(fence);
338	  return match ? match[1]! : text;
339	}
340	
341	function extractJsonObject(text: string): string | null {
342	  const start = text.indexOf("{");
343	  if (start < 0) return null;
344	  let depth = 0;
345	  let inString = false;
346	  let escape = false;
347	  for (let i = start; i < text.length; i++) {
348	    const ch = text[i]!;
349	    if (escape) {
350	      escape = false;
351	      continue;
352	    }
353	    if (ch === "\\") {
354	      escape = true;
355	      continue;
356	    }
357	    if (ch === '"') {
358	      inString = !inString;
359	      continue;
360	    }
361	    if (inString) continue;
362	    if (ch === "{") depth++;
363	    else if (ch === "}") {
364	      depth--;
365	      if (depth === 0) return text.slice(start, i + 1);
366	    }
367	  }
368	  return null;
369	}
370	
371	function truncate(s: string, max: number): string {
372	  if (s.length <= max) return s;
373	  return `${s.slice(0, max)}…`;
374	}
375

